import{z as d,x as p,o as n,c as m,q as l,j as i,D as r,d as t,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"自然演绎、可靠与完备","description":"","frontmatter":{"title":"自然演绎、可靠与完备","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/natural-deduction.md","filePath":"cs/natural-deduction.md","lastUpdated":1791413859000}'),B={name:"cs/natural-deduction.md"};function A(h,a,u,C,c,f){const o=p("Mermaid");return n(),m("div",null,[a[2]||(a[2]=l('<h1 id="自然演绎、可靠与完备" tabindex="-1">自然演绎、可靠与完备 <a class="header-anchor" href="#自然演绎、可靠与完备" aria-label="Permalink to &quot;自然演绎、可靠与完备&quot;">​</a></h1><div class="epigraph"><p>引入与消去规则在假设下推出结论。可靠：可证则有效。完备：有效则可证。一阶的完备把「真」收成「有限证明」，停机仍不可判定。</p><footer>—— 据 Gentzen, 1935；Gödel, 1930；Enderton 整理</footer></div><p>上一课<a href="/cs/predicate-logic">谓词逻辑</a> 有语义 \\(\\models\\)，没有推导。缺口是<strong>证明系统</strong>：自然演绎（或 Hilbert、sequent）。可靠与完备。本课不把 Coq 当工具——证明助手是最后一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规则例：\\(\\to\\) 引入（在假设 \\(\\varphi\\) 下证 \\(\\psi\\) 则得 \\(\\varphi\\to\\psi\\)），\\(\\to\\) 消去（MP），\\(\\forall\\) 引入须对新鲜变元。证明是有限树。可靠：\\(\\Gamma\\vdash\\varphi\\Rightarrow\\Gamma\\models\\varphi\\)。命题完备可用真值表或 Henkin；一阶 Gödel 完备：\\(\\Gamma\\models\\varphi\\Rightarrow\\Gamma\\vdash\\varphi\\)（\\(\\Gamma\\) 可递归）。于是有效公式可枚举，但因不可判定，不能判定「停在不可证」。</p><p><span class="marginnote">直觉类比：「引入」像把假设写在草稿顶端，推出结论后把假设划掉、只留条件式（假设「退场」）；「消去」就是手里有条件式又有前件，直接用出后件。可靠性说这套纸笔游戏玩不出假结论，完备性说所有真结论都迟早玩得出来。</span></p><p><span class="marginnote">常见误区：初学者把 Gödel 的两句话撞在一起。1930 年的完备性谈的是<strong>纯一阶逻辑</strong>：有效公式皆可证；1931 年的不完备谈的是<strong>含算术的具体理论</strong>：必有真而不可证的句子。一个是逻辑本身，一个是算术理论，对象不同，并不矛盾。</span></p><p>一致性：推不出 \\(\\bot\\)。完备性证明常用极大一致扩张 + 项模型，本课要陈述不写 Henkin 全文。</p><h3 id="完备不是「什么都能证」" tabindex="-1">完备不是「什么都能证」 <a class="header-anchor" href="#完备不是「什么都能证」" aria-label="Permalink to &quot;完备不是「什么都能证」&quot;">​</a></h3><p>Gödel 不完备针对含算术的理论：真算术句子有不可证者。一阶逻辑的完备是纯逻辑有效性，对象不同。不要两句撞车。</p><p><span class="marginnote">Gentzen 自然演绎与 sequent。Gödel 1930 完备。Enderton 第 2 章。Curry–Howard 把证明当项，点名留给证明助手课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用命题小证明画一棵 \\(\\to\\) 引入树。陈述可靠（对规则归纳）与完备。指出：加进 Peano 公理后，系统仍半判定「是否从公理可证」，不判定算术真。</p>',13)),(n(),i(E,null,{default:r(()=>[s(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E5%BC%95%E5%85%A5%20%2F%20%E6%B6%88%E5%8E%BB%22%5D%20--%3E%20PF%5B%22%E6%9C%89%E9%99%90%E8%AF%81%E6%98%8E%E6%A0%91%22%5D%0A%20%20PF%20--%3E%20SOUND%5B%22%E5%8F%AF%E9%9D%A0%EF%BC%9A%E2%8A%A2%20%E2%87%92%20%E2%8A%A8%22%5D%0A%20%20PF%20--%3E%20COMPL%5B%22%E5%AE%8C%E5%A4%87%EF%BC%9A%E2%8A%A8%20%E2%87%92%20%E2%8A%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了 \\(\\vdash\\)，程序正确性可以把「从公理与不变式推出后条件」写成证明义务。自动工具用另一套规则（归结、CDCL）仍要可靠。完备性保证不漏掉有效公式，不保证找证明的时间。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},[t("为什么完备了还找不到证明：完备性只保证证明"),e("strong",null,"存在"),t("且能被逐一枚举出来，不保证枚举会停。对某个公式，机器可能已经跑了一亿行推导还没证出来——你无法区分「根本没有证明」和「证明在更后面」，因为这个区分本身不可判定。")])],-1)),a[6]||(a[6]=e("p",null,[e("a",{href:"/cs/combinators-fixed-point"},"组合子"),t(" 的 \\(Y\\) 在类型系统里往往不可型，简单类型对应的是直觉主义命题，一阶算术需要更强。点名。")],-1)),a[7]||(a[7]=e("p",null,"Sequent 演算把上下文写成 \\(\\Gamma\\Rightarrow\\Delta\\)，切割消除给出证明规范化。Hilbert 系统少规则、多公理，手证不亲。直觉主义去掉排中律，\\(\\neg\\neg\\varphi\\to\\varphi\\) 不可证，对应类型里没有一般的 double-negation 翻译除非加经典。本课古典为主，助手课再分。",-1)),(n(),i(E,null,{default:r(()=>[s(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%B8%B4%E6%97%B6%E5%81%87%E8%AE%BE%20%CF%86%22%5D%20--%3E%20S%5B%22%E5%9C%A8%E5%81%87%E8%AE%BE%E4%B8%8B%E8%AF%81%E5%87%BA%20%CF%88%22%5D%0A%20%20S%20--%3E%20DIS%5B%22%E5%81%87%E8%AE%BE%E9%80%80%E5%9C%BA%EF%BC%88discharge%EF%BC%89%22%5D%0A%20%20DIS%20--%3E%20INTRO%5B%22%E2%86%92%20%E5%BC%95%E5%85%A5%EF%BC%9A%E5%BE%97%20%CF%86%20%E2%86%92%20%CF%88%22%5D%0A%20%20G1%5B%22%E5%B7%B2%E6%9C%89%20%CF%86%20%E2%86%92%20%CF%88%22%5D%20--%3E%20MP%5B%22%E2%86%92%20%E6%B6%88%E5%8E%BB%EF%BC%88MP%EF%BC%89%22%5D%0A%20%20G2%5B%22%E5%B7%B2%E6%9C%89%20%CF%86%22%5D%20--%3E%20MP%0A%20%20MP%20--%3E%20GET%5B%22%E7%94%A8%E5%87%BA%20%CF%88%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Henkin，不引入切割消除全文。不把古典 vs 直觉主义打完。后课默认：谈到证明，即某可靠系统里的有限推导。下一课把证明对准程序：Hoare。</p><p>可靠保证证出来的都有效；完备保证有效的都有有限证明。算术理论的 Gödel 不完备是另一句，不要与一阶逻辑完备相撞。Hoare 下一课把规则对准程序状态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自然演绎用引入/消去；证明有限。</li><li>可靠与（一阶逻辑）完备：真与可证对齐。</li><li>算术理论的不完备是另一句话。</li><li>出处：Gentzen, 1935；Gödel, 1930；Enderton。</li></ul>',5))])}const F=d(B,[["render",A]]);export{D as __pageData,F as default};
